fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    let mut seed: i32 = host::display::state_get(1);
    if seed == 0 { seed = 777777; }
    if down == 1 && prev == 0 {
        seed = seed * 1103515245 + 12345;
        host::display::state_set(1, seed);
    }
    host::display::state_set(0, down);
    let mut sx = [0; 6];
    let mut sy = [0; 6];
    let mut i: i32 = 0;
    while i < 6 {
        let mut hsh: i32 = seed + i * 2654435761;
        hsh = hsh * 1103515245 + 12345;
        sx[i] = ((hsh >> 16) & 32767) % w;
        hsh = hsh * 1103515245 + 12345;
        sy[i] = ((hsh >> 16) & 32767) % h;
        i = i + 1;
    }
    let pal = [0x264653, 0x2a9d8f, 0xe9c46a, 0xf4a261, 0xe76f51, 0x8ab17d];
    let cell: i32 = 8;
    let mut y: i32 = 0;
    while y < h {
        let mut x: i32 = 0;
        while x < w {
            let mx: i32 = x + cell / 2;
            let my: i32 = y + cell / 2;
            let mut best: i32 = 0;
            let mut bd: i32 = 99999999;
            let mut s: i32 = 0;
            while s < 6 {
                let d: i32 = (mx - sx[s]) * (mx - sx[s]) + (my - sy[s]) * (my - sy[s]);
                if d < bd {
                    bd = d;
                    best = s;
                }
                s = s + 1;
            }
            host::display::fill_rect(x, y, cell, cell, pal[best]);
            x = x + cell;
        }
        y = y + cell;
    }
    let mut j: i32 = 0;
    while j < 6 {
        host::display::fill_rect(sx[j] - 3, sy[j] - 3, 6, 6, 0x101010);
        j = j + 1;
    }
    host::display::present();
}
